// Package jsconsumer is the durable JetStream pull-consumer scaffold shared by
// Entire's decode-and-dispatch consumers. Each of those used to hand-roll the
// same lifecycle: jetstream.New → CreateOrUpdateConsumer (durable, explicit
// ack, bounded ack-wait, bounded MaxDeliver, filter subject) → Consume → stop
// on context cancel; and the same per-message prologue: open a consumer span
// (re-parented across the NATS hop), decode the payload, and Term on a decode
// error.
//
// This package owns exactly that scaffold and nothing else. Each consumer
// keeps its OWN event type, business dispatch, metrics, and log lines — Start
// takes the consumer's message callback, and Process invokes the consumer's
// handle with the decoded event and the live span. The handler owns the
// message's terminal disposition (Ack/Nak/Term); Process never touches a
// message that decoded.
//
// Lifted from entire-api's internal/jsconsumer (COR-929), folding in the
// module's shutdown classification ([nuts.IsShutdownFetchErr] gates the
// consume-error log so a drain during rollout isn't reported as a fault,
// COR-923) and an optional [natsmsg.KeepInProgress] heartbeat for consumers
// whose handlers legitimately outrun AckWait.
package jsconsumer

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entireio/go-nuts"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	// defaultAckWait is how long JetStream waits for an ack before redelivery
	// when Config.AckWait is zero — comfortably longer than an RPC round-trip
	// plus a DB upsert, short enough that a stuck message redelivers promptly.
	defaultAckWait = 30 * time.Second
	// defaultMaxDeliver caps redelivery before JetStream stops redelivering a
	// message when Config.MaxDeliver is zero.
	defaultMaxDeliver = 8
)

// Config describes the durable consumer to create and how to trace/log it. The
// filter is given as either FilterSubject (single) or FilterSubjects (multi),
// mirroring jetstream.ConsumerConfig, so a migrated consumer preserves its
// existing on-server filter form exactly.
type Config struct {
	Stream         string        // JetStream stream to bind (must already exist)
	Durable        string        // durable consumer name, stable across restarts
	FilterSubject  string        // set this OR FilterSubjects
	FilterSubjects []string      // set this OR FilterSubject
	AckWait        time.Duration // 0 → defaultAckWait
	MaxDeliver     int           // 0 → defaultMaxDeliver
	SpanName       string        // per-message consumer span name (e.g. "repolifecycle.consume")
	Name           string        // short consumer name, used as the log prefix

	// Tracer opens the per-message consumer span; nil uses the global OTel
	// tracer provider.
	Tracer trace.Tracer
	// Logger receives the scaffold's own log lines (decode-term warnings,
	// consume errors); nil uses slog.Default.
	Logger *slog.Logger

	// KeepInProgress runs a natsmsg.KeepInProgress heartbeat while handle
	// executes, for handlers that legitimately outrun AckWait. The extension
	// is capped, so a wedged handler still redelivers — see
	// natsmsg.KeepInProgress. The heartbeat stops when handle returns; a tick
	// racing the handler's own terminal Ack/Nak/Term is a client-side no-op
	// (nats.go marks the message disposed locally) that halts the heartbeat.
	KeepInProgress bool
}

func (c Config) ackWait() time.Duration {
	if c.AckWait == 0 {
		return defaultAckWait
	}
	return c.AckWait
}

func (c Config) maxDeliver() int {
	if c.MaxDeliver == 0 {
		return defaultMaxDeliver
	}
	return c.MaxDeliver
}

func (c Config) tracer() trace.Tracer {
	if c.Tracer == nil {
		return otel.Tracer("github.com/entireio/go-nuts/jsconsumer")
	}
	return c.Tracer
}

func (c Config) logger() *slog.Logger {
	if c.Logger == nil {
		return slog.Default()
	}
	return c.Logger
}

// Runner is a live consume loop. Stop halts it and is idempotent.
type Runner struct{ cc jetstream.ConsumeContext }

// Stop halts the consume loop. Safe on a nil Runner and safe to call twice.
func (r *Runner) Stop() {
	if r != nil && r.cc != nil {
		r.cc.Stop()
		r.cc = nil
	}
}

// Start creates/updates the durable consumer on nc and begins delivering
// messages to onMsg, returning a Runner that Stops when ctx is cancelled. The
// stream must already exist (provisioned declaratively); callers whose cells
// opt in per-stream gate Start behind that opt-in so a cell without the stream
// doesn't error at CreateOrUpdateConsumer.
//
// Consume errors are logged at Warn, except a drain/close during shutdown
// ([nuts.IsShutdownFetchErr]), which is a clean exit rather than a fault.
func Start(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) (*Runner, error) {
	if nc == nil {
		return nil, fmt.Errorf("jsconsumer(%s): nil nats conn", cfg.Name)
	}
	js, err := jetstream.New(nc)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): jetstream.New: %w", cfg.Name, err)
	}
	cons, err := js.CreateOrUpdateConsumer(ctx, cfg.Stream, jetstream.ConsumerConfig{
		Durable:        cfg.Durable,
		AckPolicy:      jetstream.AckExplicitPolicy,
		AckWait:        cfg.ackWait(),
		MaxDeliver:     cfg.maxDeliver(),
		FilterSubject:  cfg.FilterSubject,
		FilterSubjects: cfg.FilterSubjects,
	})
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): create consumer %s/%s: %w", cfg.Name, cfg.Stream, cfg.Durable, err)
	}
	cc, err := cons.Consume(onMsg, jetstream.ConsumeErrHandler(func(_ jetstream.ConsumeContext, cerr error) {
		if nuts.IsShutdownFetchErr(ctx, cerr) {
			return
		}
		cfg.logger().WarnContext(ctx, cfg.Name+": consume error", slog.Any("error", cerr))
	}))
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): consume %s: %w", cfg.Name, cfg.Stream, err)
	}
	r := &Runner{cc: cc}
	go func() {
		<-ctx.Done()
		r.Stop()
	}()
	return r, nil
}

// Process runs the per-message prologue shared by every consumer: open the
// consumer span (re-parented to the producer across the NATS hop), decode the
// payload, and on a decode error record it, log "<Name>: decode <Stream>;
// term", invoke onUndecodable (so the caller bumps its own drop metric with
// its own attributes), and Term the message — a poison payload won't decode on
// redelivery. On success it invokes handle with the span-enriched context, the
// live span (for RecordError/SetStatus on the business error paths), the
// message, and the decoded event; with Config.KeepInProgress set, an AckWait
// heartbeat runs for the duration of handle.
//
// Callers wire Process as the func they pass to Start AND the entry point
// their tests drive, so the decode-or-term path is exercised the same way in
// production and tests.
func Process[E any](
	ctx context.Context,
	msg jetstream.Msg,
	cfg Config,
	decode func([]byte) (E, error),
	handle func(ctx context.Context, span trace.Span, msg jetstream.Msg, ev E),
	onUndecodable func(ctx context.Context),
) {
	ctx, span := natsmsg.StartConsumerSpan(ctx, cfg.tracer(), msg, cfg.SpanName)
	defer span.End()

	ev, err := decode(msg.Data())
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		cfg.logger().WarnContext(ctx, cfg.Name+": decode "+cfg.Stream+"; term",
			slog.Any("error", err), slog.String("subject", msg.Subject()))
		if onUndecodable != nil {
			onUndecodable(ctx)
		}
		if termErr := msg.Term(); termErr != nil {
			cfg.logger().WarnContext(ctx, cfg.Name+": term failed", slog.Any("error", termErr))
		}
		return
	}
	if cfg.KeepInProgress {
		stop := natsmsg.KeepInProgress(msg.InProgress, cfg.ackWait())
		defer stop()
	}
	handle(ctx, span, msg, ev)
}
package natsmsg

import (
	"sync"
	"time"
)

// keepInProgressMaxTicks caps the total AckWait extension at ~5×AckWait
// (ticks fire at AckWait/3). The heartbeat exists so a long handler that IS
// making progress — a whole-installation teardown fan-out, a multi-GB
// data-plane purge — doesn't get redelivered into a concurrent duplicate;
// it must NOT remove the broker's liveness failsafe entirely, or a wedged
// handler (hung I/O with no deadline) would pin its delivery to the wedged
// replica forever. Past the cap the extension stops and AckWait expiry
// redelivers to a healthy replica sharing the durable.
const keepInProgressMaxTicks = 15

// KeepInProgress calls inProgress at ackWait/3 until stop is called, resetting
// the broker's redelivery timer while a long handler runs. The extension is
// capped (keepInProgressMaxTicks) — see the constant for why.
//
// inProgress wraps the message's InProgress call — func() error { return
// msg.InProgress() }. The func() error callback keeps this helper decoupled
// from the jetstream package.
//
// A non-positive interval (zero ackWait on a hand-built consumer; real
// consumer configs default it) returns a no-op stop.
//
// stop is idempotent and blocks until the ticker goroutine has exited, so
// no InProgress can race a terminal disposition (Ack/Nak/Term) issued
// after it returns.
func KeepInProgress(inProgress func() error, ackWait time.Duration) (stop func()) {
	interval := ackWait / 3
	if interval <= 0 {
		return func() {}
	}
	done := make(chan struct{})
	finished := make(chan struct{})
	go func() {
		defer close(finished)
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for ticks := 0; ; {
			select {
			case <-done:
				return
			case <-ticker.C:
				ticks++
				if ticks > keepInProgressMaxTicks {
					return
				}
				if err := inProgress(); err != nil {
					// A delivery that can't be extended (no JetStream
					// reply subject, or already terminally disposed)
					// won't start succeeding on a later tick; stop
					// instead of spinning. The real failure surfaces
					// on the terminal Ack/Nak/Term.
					return
				}
			}
		}
	}()
	var once sync.Once
	return func() {
		once.Do(func() { close(done) })
		<-finished
	}
}
// Package natsmsg holds small JetStream message helpers shared by Entire's
// NATS consumers: W3C trace-context propagation over message headers (so a
// consumer span parents to the remote producer span and publish → consume
// stitches into one trace) and a KeepInProgress heartbeat for long-running
// handlers.
//
// It unifies two service-local copies — entire-core's internal/natsmsg and
// entire-api's internal/otelnats (itself ported from mirror-pipeline) — into
// the one shared implementation. Tracking: COR-929.
package natsmsg

import (
	"context"
	"math"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/propagation"
	"go.opentelemetry.io/otel/trace"
)

// HeaderCarrier adapts nats.Header to the OTel TextMapCarrier contract so the
// configured propagator can inject/extract traceparent and baggage over a
// NATS hop.
type HeaderCarrier nats.Header

func (c HeaderCarrier) Get(key string) string {
	v := nats.Header(c).Values(key)
	if len(v) == 0 {
		return ""
	}
	return v[0]
}

func (c HeaderCarrier) Set(key, value string) { nats.Header(c).Set(key, value) }

func (c HeaderCarrier) Keys() []string {
	keys := make([]string, 0, len(c))
	for k := range c {
		keys = append(keys, k)
	}
	return keys
}

var _ propagation.TextMapCarrier = HeaderCarrier(nil)

// Inject writes the propagator state from ctx into msg.Header, creating the
// header map if absent. Call before publishing so the consumer can re-parent.
func Inject(ctx context.Context, msg *nats.Msg) {
	if msg.Header == nil {
		msg.Header = nats.Header{}
	}
	otel.GetTextMapPropagator().Inject(ctx, HeaderCarrier(msg.Header))
}

// Extract returns ctx with propagator state from msg.Header applied. Call
// before starting the consumer span so it parents to the remote producer.
func Extract(ctx context.Context, msg *nats.Msg) context.Context {
	return ExtractHeader(ctx, msg.Header)
}

// ExtractHeader is Extract over a bare nats.Header — it takes the header map
// rather than the message so it serves both *nats.Msg (msg.Header) and
// jetstream.Msg (msg.Headers()).
func ExtractHeader(ctx context.Context, h nats.Header) context.Context {
	if h == nil {
		return ctx
	}
	return otel.GetTextMapPropagator().Extract(ctx, HeaderCarrier(h))
}

// Message is the subset of jetstream.Msg the consumer-span helper needs.
type Message interface {
	Headers() nats.Header
	Subject() string
}

// StartConsumerSpan extracts the propagated trace context from msg's headers
// and opens a consumer span named name on tr, pre-tagged with the standard
// messaging attributes (system=nats, destination=subject). Extra attrs are
// appended. Collapses the extract+start boilerplate shared by every JetStream
// consumer.
func StartConsumerSpan(ctx context.Context, tr trace.Tracer, msg Message, name string, attrs ...attribute.KeyValue) (context.Context, trace.Span) {
	ctx = ExtractHeader(ctx, msg.Headers())
	base := append([]attribute.KeyValue{
		attribute.String("messaging.system", "nats"),
		attribute.String("messaging.destination.name", msg.Subject()),
	}, attrs...)
	return tr.Start(ctx, name, trace.WithSpanKind(trace.SpanKindConsumer), trace.WithAttributes(base...)) //nolint:spancheck // the caller owns the span and Ends it
}

// ClampToInt64 narrows a JetStream sequence / delivery count (uint64 on the
// wire) to the int64 OTel attributes take, saturating instead of wrapping.
func ClampToInt64(v uint64) int64 {
	if v > math.MaxInt64 {
		return math.MaxInt64
	}
	return int64(v)
}
// Package backoff is the redelivery policy for transiently-failed JetStream
// deliveries: a flat NakWithDelay envelope bounded by MaxDeliver, with an
// optional Term on the final delivery.
//
// The Term-on-exhaustion posture is the COR-762 fix, lifted from
// mirror-pipeline's fanoutengine: on the final delivery a Nak is dropped
// silently by the broker (MaxDeliver reached), and on a WorkQueue stream the
// un-acked message then orphans — pinning the oldest-pending-age gauge — until
// StreamMaxAge finally expires it. Terming instead removes it cleanly. Streams
// where lingering is acceptable (a webhook stream whose max_age doubles as the
// retry backstop) leave TermOnExhaustion off and keep the plain Nak.
//
// The policy owns disposition only. Dead-letter capture stays with the caller,
// which should capture BEFORE disposing — gate it on [IsFinalDelivery]:
//
//	if backoff.IsFinalDelivery(msg, p.MaxDeliver) {
//		captureToDLQ(ctx, msg)
//	}
//	outcome, err := p.NakOrTerm(msg)
package backoff

import (
	"fmt"
	"time"

	"github.com/nats-io/nats.go/jetstream"
)

// Outcome is the disposition NakOrTerm chose, for the caller's metrics and
// logs.
type Outcome string

const (
	OutcomeNak  Outcome = "nak"
	OutcomeTerm Outcome = "term"
)

// Policy is the flat redelivery envelope a consumer applies to transient
// failures. MaxDeliver must match the consumer's on-server MaxDeliver — the
// policy detects the final delivery by comparing against it.
type Policy struct {
	// NakDelay is the flat delay before redelivery. Flat, not growing: the
	// envelope only rides out transient failures; MaxDeliver bounds the total.
	NakDelay time.Duration
	// MaxDeliver is the consumer's redelivery cap
	// (jetstream.ConsumerConfig.MaxDeliver). Non-positive means unlimited
	// redeliveries — matching the jetstream field's semantics — so no
	// delivery is ever final and NakOrTerm always Naks.
	MaxDeliver int
	// TermOnExhaustion makes the final delivery Term instead of Nak, so a
	// work-queue message is removed cleanly rather than orphaning un-acked
	// (COR-762). Callers with a DLQ capture before calling NakOrTerm.
	TermOnExhaustion bool
}

// NakOrTerm applies the policy to a transiently-failed delivery: NakWithDelay
// for redelivery, or — on the final delivery with TermOnExhaustion set — Term.
// Without TermOnExhaustion the final delivery still Naks; the broker drops the
// Nak at MaxDeliver and the stream's retention decides the message's fate.
//
// The returned Outcome reports which disposition was chosen, for the caller's
// metrics and logs. A disposition error is worth a log line but nothing more:
// a failed Nak redelivers via AckWait expiry anyway, and a failed Term on a
// work-queue stream means the message lingers exactly as it would have without
// the policy.
func (p Policy) NakOrTerm(msg jetstream.Msg) (Outcome, error) {
	if p.TermOnExhaustion && IsFinalDelivery(msg, p.MaxDeliver) {
		if err := msg.Term(); err != nil {
			return OutcomeTerm, fmt.Errorf("term on final delivery: %w", err)
		}
		return OutcomeTerm, nil
	}
	if err := msg.NakWithDelay(p.NakDelay); err != nil {
		return OutcomeNak, fmt.Errorf("nak with delay: %w", err)
	}
	return OutcomeNak, nil
}

// NumDelivered reports the JetStream delivery count (1 on first delivery), or
// 0 if metadata is unavailable (e.g. a synthetic test message).
func NumDelivered(msg jetstream.Msg) int {
	if meta, err := msg.Metadata(); err == nil {
		return int(meta.NumDelivered)
	}
	return 0
}

// IsFinalDelivery reports whether this is the last delivery before JetStream
// stops redelivering (NumDelivered has reached MaxDeliver), so a transient
// failure here is terminal rather than another Nak-and-retry. A non-positive
// maxDeliver means unlimited redeliveries (the jetstream.ConsumerConfig
// semantics), so no delivery is final — without the guard the zero value
// would read every delivery as final and Term on the first failure.
// Unavailable metadata also reads as non-final: the safe default is another
// retry, not a Term.
func IsFinalDelivery(msg jetstream.Msg, maxDeliver int) bool {
	if maxDeliver <= 0 {
		return false
	}
	if meta, err := msg.Metadata(); err == nil {
		return meta.NumDelivered >= uint64(maxDeliver)
	}
	return false
}
