package jsconsumer

import (
	"context"
	"errors"
	"testing"
	"time"

	natsserver "github.com/nats-io/nats-server/v2/server"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/trace"

	"github.com/entireio/go-nuts/natsmsg/natsmsgtest"
)

var testCfg = Config{Stream: "s_v1", Name: "testconsumer", SpanName: "test.consume"}

// TestProcessDispatchesDecodedEvent: a payload that decodes reaches handle with the
// decoded event and a live span; the message is left for handle to ack/nak (Process
// does not touch it), and onUndecodable is not called.
func TestProcessDispatchesDecodedEvent(t *testing.T) {
	msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
	var (
		gotEv   string
		gotSpan trace.Span
		gotMsg  jetstream.Msg
		dropped bool
	)
	decode := func(b []byte) (string, error) { return "decoded:" + string(b), nil }
	handle := func(_ context.Context, span trace.Span, m jetstream.Msg, ev string) {
		gotEv, gotSpan, gotMsg = ev, span, m
	}
	Process(context.Background(), msg, testCfg, decode, handle, func(context.Context) { dropped = true })

	if gotEv != "decoded:payload" {
		t.Errorf("handle got ev %q, want decoded:payload", gotEv)
	}
	if gotSpan == nil {
		t.Error("handle got a nil span, want the live consumer span")
	}
	if gotMsg != msg {
		t.Error("handle got a different msg than the one passed to Process")
	}
	if msg.Acked || msg.Termed || len(msg.NakDelays) > 0 {
		t.Error("Process disposed the message, want none (handle owns ack/nak)")
	}
	if dropped {
		t.Error("onUndecodable called on a successful decode")
	}
}

// TestProcessTermsUndecodable: a decode error terms the message, bumps the caller's
// drop metric via onUndecodable, and never calls handle — a poison payload won't
// decode on redelivery.
func TestProcessTermsUndecodable(t *testing.T) {
	msg := &natsmsgtest.FakeMsg{DataVal: []byte("garbage")}
	handled := false
	dropped := false
	decode := func([]byte) (string, error) { return "", errors.New("bad payload") }
	handle := func(context.Context, trace.Span, jetstream.Msg, string) { handled = true }
	Process(context.Background(), msg, testCfg, decode, handle, func(context.Context) { dropped = true })

	if !msg.Termed {
		t.Error("message not termed on a decode error")
	}
	if !dropped {
		t.Error("onUndecodable not called on a decode error")
	}
	if handled {
		t.Error("handle called despite a decode error")
	}
}

// TestProcessNilOnUndecodable: a nil onUndecodable is tolerated (still terms).
func TestProcessNilOnUndecodable(t *testing.T) {
	msg := &natsmsgtest.FakeMsg{DataVal: []byte("garbage")}
	decode := func([]byte) (string, error) { return "", errors.New("bad") }
	Process(context.Background(), msg, testCfg, decode,
		func(context.Context, trace.Span, jetstream.Msg, string) {}, nil)
	if !msg.Termed {
		t.Error("message not termed")
	}
}

// TestProcessKeepInProgress: with Config.KeepInProgress set, a handler that
// outruns AckWait/3 gets InProgress heartbeats, and the heartbeat goroutine has
// stopped by the time Process returns (no further ticks accrue).
func TestProcessKeepInProgress(t *testing.T) {
	cfg := testCfg
	cfg.KeepInProgress = true
	cfg.AckWait = 30 * time.Millisecond // ticks at 10ms

	msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
	decode := func(b []byte) (string, error) { return string(b), nil }
	handle := func(context.Context, trace.Span, jetstream.Msg, string) {
		time.Sleep(35 * time.Millisecond) // spans at least three ticks
	}
	Process(context.Background(), msg, cfg, decode, handle, nil)

	after := msg.InProgressN
	if after == 0 {
		t.Fatal("no InProgress heartbeat during a long handler")
	}
	time.Sleep(25 * time.Millisecond)
	if msg.InProgressN != after {
		t.Errorf("heartbeat still ticking after Process returned: %d → %d", after, msg.InProgressN)
	}
}

// TestProcessNoKeepInProgressByDefault: without the opt-in, a long handler gets
// no heartbeat — the broker's AckWait failsafe stays untouched.
func TestProcessNoKeepInProgressByDefault(t *testing.T) {
	cfg := testCfg
	cfg.AckWait = 30 * time.Millisecond

	msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
	decode := func(b []byte) (string, error) { return string(b), nil }
	handle := func(context.Context, trace.Span, jetstream.Msg, string) {
		time.Sleep(35 * time.Millisecond)
	}
	Process(context.Background(), msg, cfg, decode, handle, nil)

	if msg.InProgressN != 0 {
		t.Errorf("InProgress called %d times without KeepInProgress opt-in", msg.InProgressN)
	}
}

// TestRunnerStopIdempotent: Stop is safe on a nil Runner, a zero Runner, and
// twice. A panic on any of these fails the test.
func TestRunnerStopIdempotent(_ *testing.T) {
	var nilRunner *Runner
	nilRunner.Stop() // must not panic

	r := &Runner{} // cc nil (never Started)
	r.Stop()
	r.Stop() // second call is a no-op
}

// TestStartNilConn: a nil connection is rejected up front, not on first use.
func TestStartNilConn(t *testing.T) {
	if _, err := Start(context.Background(), nil, testCfg, func(jetstream.Msg) {}); err == nil {
		t.Fatal("Start(nil conn) succeeded, want error")
	}
}

// runJetStreamServer starts an in-process JetStream-enabled NATS server on a
// random loopback port and returns its client URL.
func runJetStreamServer(t *testing.T) string {
	t.Helper()
	s, err := natsserver.NewServer(&natsserver.Options{
		Host:      "127.0.0.1",
		Port:      -1, // pick a free port
		NoLog:     true,
		NoSigs:    true,
		JetStream: true,
		StoreDir:  t.TempDir(),
	})
	if err != nil {
		t.Fatalf("new embedded nats server: %v", err)
	}
	go s.Start()
	if !s.ReadyForConnections(10 * time.Second) {
		t.Fatal("embedded nats server not ready in time")
	}
	t.Cleanup(s.Shutdown)
	return s.ClientURL()
}

// TestStartDeliversToOnMsg drives the whole scaffold against an embedded
// JetStream server: Start creates the durable, a published message reaches
// onMsg, and cancelling ctx stops the runner.
func TestStartDeliversToOnMsg(t *testing.T) {
	url := runJetStreamServer(t)
	nc, err := nats.Connect(url)
	if err != nil {
		t.Fatalf("connect: %v", err)
	}
	t.Cleanup(nc.Close)

	js, err := jetstream.New(nc)
	if err != nil {
		t.Fatalf("jetstream.New: %v", err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if _, err := js.CreateStream(ctx, jetstream.StreamConfig{
		Name: "events_v1", Subjects: []string{"events.>"},
	}); err != nil {
		t.Fatalf("create stream: %v", err)
	}

	got := make(chan jetstream.Msg, 1)
	run, err := Start(ctx, nc, Config{
		Stream:        "events_v1",
		Durable:       "test_durable",
		FilterSubject: "events.repo",
		Name:          "testconsumer",
		SpanName:      "test.consume",
	}, func(m jetstream.Msg) {
		if err := m.Ack(); err != nil {
			t.Errorf("ack: %v", err)
		}
		got <- m
	})
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer run.Stop()

	if _, err := js.Publish(ctx, "events.repo", []byte("hello")); err != nil {
		t.Fatalf("publish: %v", err)
	}
	select {
	case m := <-got:
		if string(m.Data()) != "hello" {
			t.Errorf("payload = %q, want hello", m.Data())
		}
	case <-time.After(5 * time.Second):
		t.Fatal("message did not reach onMsg")
	}
}
package natsmsg

import (
	"errors"
	"testing"
	"time"
)

// noopInProgress and failingInProgress stand in for the message's InProgress
// call that consumers pass to KeepInProgress (func() error { return
// msg.InProgress() }): one keeps the heartbeat ticking, one drives the
// handled-error exit path.
func noopInProgress() error    { return nil }
func failingInProgress() error { return errors.New("in progress failed") }

// TestKeepInProgress_StopIsIdempotentAndTerminates smoke-tests the long-handler
// keepalive: with a succeeding callback the ticker goroutine keeps running, and
// stop must terminate that live goroutine, be safe to call twice, and block
// until it has exited — the guarantee consumers lean on so no InProgress can
// race a terminal Ack/Nak/Term.
func TestKeepInProgress_StopIsIdempotentAndTerminates(t *testing.T) {
	stop := KeepInProgress(noopInProgress, 30*time.Millisecond)
	time.Sleep(50 * time.Millisecond) // spans at least one tick (10ms interval)

	done := make(chan struct{})
	go func() {
		stop()
		stop() // idempotent: an explicit call and a deferred one both run
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("stop did not terminate the heartbeat goroutine")
	}
}

// TestKeepInProgress_NonPositiveIntervalIsNoop pins the guard for a zero
// ackWait (possible only on a hand-built consumer config; real consumer
// configs default it): no goroutine, and stop returns immediately.
func TestKeepInProgress_NonPositiveIntervalIsNoop(t *testing.T) {
	stop := KeepInProgress(noopInProgress, 0)
	done := make(chan struct{})
	go func() {
		stop()
		stop() // double-stop must be as safe as on the ticking path
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("no-op stop did not return")
	}
}

// TestKeepInProgress_CapTerminatesTheGoroutine pins the wedged-handler failsafe:
// even with a callback that keeps succeeding, after keepInProgressMaxTicks the
// goroutine exits on its own — without stop being called — so AckWait expiry can
// eventually redeliver a delivery whose handler never returns. Observed via stop
// returning promptly long after the cap has passed.
func TestKeepInProgress_CapTerminatesTheGoroutine(t *testing.T) {
	stop := KeepInProgress(noopInProgress, 3*time.Millisecond) // interval 1ms → cap at ~15ms
	time.Sleep(time.Duration(keepInProgressMaxTicks+5) * time.Millisecond)

	done := make(chan struct{})
	go func() {
		stop()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("heartbeat goroutine still alive after the cap")
	}
}

// TestKeepInProgress_CallbackErrorStopsTheGoroutine pins the handled-error path:
// a callback that can't extend the delivery (no reply subject, already disposed)
// exits the goroutine rather than spinning. Observed via stop returning promptly
// even though the goroutine has already exited on its own.
func TestKeepInProgress_CallbackErrorStopsTheGoroutine(t *testing.T) {
	stop := KeepInProgress(failingInProgress, 3*time.Millisecond)
	time.Sleep(20 * time.Millisecond) // several intervals; the first tick already errored out

	done := make(chan struct{})
	go func() {
		stop()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("goroutine did not exit after the callback errored")
	}
}
package natsmsg

import (
	"context"
	"math"
	"os"
	"testing"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/propagation"
	"go.opentelemetry.io/otel/trace"
)

func TestMain(m *testing.M) {
	// Inject/Extract round-trip needs a configured propagator; services set
	// this in their otel setup.
	otel.SetTextMapPropagator(propagation.TraceContext{})
	os.Exit(m.Run())
}

// remoteSpanCtx builds a sampled remote span context to stand in for the
// producer-side trace a publisher would inject.
func remoteSpanCtx(t *testing.T) (context.Context, trace.TraceID, trace.SpanID) {
	t.Helper()
	tid, err := trace.TraceIDFromHex("0123456789abcdef0123456789abcdef")
	if err != nil {
		t.Fatalf("trace id: %v", err)
	}
	sid, err := trace.SpanIDFromHex("0123456789abcdef")
	if err != nil {
		t.Fatalf("span id: %v", err)
	}
	sc := trace.NewSpanContext(trace.SpanContextConfig{
		TraceID:    tid,
		SpanID:     sid,
		TraceFlags: trace.FlagsSampled,
		Remote:     true,
	})
	return trace.ContextWithSpanContext(context.Background(), sc), tid, sid
}

func TestInjectExtractRoundTrip(t *testing.T) {
	ctx, tid, sid := remoteSpanCtx(t)

	msg := &nats.Msg{Subject: "x"}
	Inject(ctx, msg)
	if len(msg.Header) == 0 {
		t.Fatal("Inject wrote no headers")
	}

	got := trace.SpanContextFromContext(Extract(context.Background(), msg))
	if got.TraceID() != tid {
		t.Errorf("trace id: got %s want %s", got.TraceID(), tid)
	}
	if got.SpanID() != sid {
		t.Errorf("span id: got %s want %s", got.SpanID(), sid)
	}
}

func TestExtractHeaderNilIsNoop(t *testing.T) {
	ctx := context.Background()
	if ExtractHeader(ctx, nil) != ctx {
		t.Error("ExtractHeader(nil) should return ctx unchanged")
	}
}

// fakeHeaderMsg is the minimal Message for StartConsumerSpan: headers carry
// the producer's injected trace context.
type fakeHeaderMsg struct {
	subject string
	header  nats.Header
}

func (m fakeHeaderMsg) Headers() nats.Header { return m.header }
func (m fakeHeaderMsg) Subject() string      { return m.subject }

// TestStartConsumerSpanReparents pins the re-parenting across the NATS hop:
// the context StartConsumerSpan returns must carry the trace id the producer
// injected into the message headers, so the consumer span joins the
// producer's trace instead of starting a fresh one. Uses the global (noop)
// tracer — extraction happens before the span starts, so the propagated span
// context is observable on the returned ctx without an SDK.
func TestStartConsumerSpanReparents(t *testing.T) {
	prodCtx, tid, _ := remoteSpanCtx(t)
	pub := &nats.Msg{Subject: "events.repo"}
	Inject(prodCtx, pub)

	ctx, span := StartConsumerSpan(context.Background(), otel.Tracer("test"),
		fakeHeaderMsg{subject: pub.Subject, header: pub.Header}, "test.consume")
	defer span.End()

	if got := trace.SpanContextFromContext(ctx).TraceID(); got != tid {
		t.Errorf("consumer ctx trace id: got %s want %s", got, tid)
	}
}

func TestClampToInt64(t *testing.T) {
	if got := ClampToInt64(7); got != 7 {
		t.Errorf("ClampToInt64(7) = %d", got)
	}
	if got := ClampToInt64(math.MaxUint64); got != math.MaxInt64 {
		t.Errorf("ClampToInt64(MaxUint64) = %d, want MaxInt64", got)
	}
}
package backoff

import (
	"errors"
	"testing"
	"time"

	"github.com/nats-io/nats.go/jetstream"

	"github.com/entireio/go-nuts/natsmsg/natsmsgtest"
)

const testDelay = 5 * time.Second

func delivered(n uint64) *natsmsgtest.FakeMsg {
	return &natsmsgtest.FakeMsg{Meta: &jetstream.MsgMetadata{NumDelivered: n}}
}

// TestNakOrTermNaksBeforeExhaustion: a transient failure with deliveries left
// redelivers with the flat policy delay.
func TestNakOrTermNaksBeforeExhaustion(t *testing.T) {
	p := Policy{NakDelay: testDelay, MaxDeliver: 5, TermOnExhaustion: true}
	msg := delivered(4)

	got, err := p.NakOrTerm(msg)
	if err != nil {
		t.Fatalf("NakOrTerm: %v", err)
	}
	if got != OutcomeNak {
		t.Errorf("outcome = %q, want nak", got)
	}
	if len(msg.NakDelays) != 1 || msg.NakDelays[0] != testDelay {
		t.Errorf("NakDelays = %v, want one nak with the policy delay", msg.NakDelays)
	}
	if msg.Termed {
		t.Error("termed before exhaustion")
	}
}

// TestNakOrTermTermsOnFinalDelivery pins the COR-762 fix: on the final delivery
// of a work-queue consumer (TermOnExhaustion), Term removes the message cleanly
// instead of a Nak the broker drops — which would orphan it un-acked until
// StreamMaxAge.
func TestNakOrTermTermsOnFinalDelivery(t *testing.T) {
	p := Policy{NakDelay: testDelay, MaxDeliver: 5, TermOnExhaustion: true}
	msg := delivered(5)

	got, err := p.NakOrTerm(msg)
	if err != nil {
		t.Fatalf("NakOrTerm: %v", err)
	}
	if got != OutcomeTerm {
		t.Errorf("outcome = %q, want term", got)
	}
	if !msg.Termed {
		t.Error("final delivery not termed")
	}
	if len(msg.NakDelays) != 0 {
		t.Errorf("NakDelays = %v, want none on the term path", msg.NakDelays)
	}
}

// TestNakOrTermKeepsNakWithoutOptIn: without TermOnExhaustion the final
// delivery still Naks — streams whose max_age doubles as the retry backstop
// keep their existing posture.
func TestNakOrTermKeepsNakWithoutOptIn(t *testing.T) {
	p := Policy{NakDelay: testDelay, MaxDeliver: 5}
	msg := delivered(5)

	got, err := p.NakOrTerm(msg)
	if err != nil {
		t.Fatalf("NakOrTerm: %v", err)
	}
	if got != OutcomeNak {
		t.Errorf("outcome = %q, want nak", got)
	}
	if msg.Termed {
		t.Error("termed without the TermOnExhaustion opt-in")
	}
}

// TestNakOrTermMissingMetadataNaks: a message without JetStream metadata (a
// synthetic test message) reads as non-final — the safe default is another
// retry, never a Term.
func TestNakOrTermMissingMetadataNaks(t *testing.T) {
	p := Policy{NakDelay: testDelay, MaxDeliver: 1, TermOnExhaustion: true}
	msg := &natsmsgtest.FakeMsg{MetaErr: errors.New("no metadata")}

	got, err := p.NakOrTerm(msg)
	if err != nil {
		t.Fatalf("NakOrTerm: %v", err)
	}
	if got != OutcomeNak {
		t.Errorf("outcome = %q, want nak", got)
	}
	if msg.Termed {
		t.Error("termed a message whose delivery count is unknown")
	}
}

// TestNakOrTermZeroMaxDeliverNaks pins the zero-value guard: MaxDeliver left
// at 0 means unlimited redeliveries (the jetstream.ConsumerConfig semantics),
// so no delivery is final and a transient failure Naks — it must NOT read
// every delivery as final and Term on the first failure.
func TestNakOrTermZeroMaxDeliverNaks(t *testing.T) {
	p := Policy{NakDelay: testDelay, TermOnExhaustion: true} // MaxDeliver unset
	msg := delivered(1)

	got, err := p.NakOrTerm(msg)
	if err != nil {
		t.Fatalf("NakOrTerm: %v", err)
	}
	if got != OutcomeNak {
		t.Errorf("outcome = %q, want nak", got)
	}
	if msg.Termed {
		t.Error("termed on the first delivery with an unset MaxDeliver")
	}
}

func TestNumDelivered(t *testing.T) {
	if got := NumDelivered(delivered(3)); got != 3 {
		t.Errorf("NumDelivered = %d, want 3", got)
	}
	if got := NumDelivered(&natsmsgtest.FakeMsg{MetaErr: errors.New("none")}); got != 0 {
		t.Errorf("NumDelivered without metadata = %d, want 0", got)
	}
}

func TestIsFinalDelivery(t *testing.T) {
	if IsFinalDelivery(delivered(4), 5) {
		t.Error("delivery 4/5 read as final")
	}
	if !IsFinalDelivery(delivered(5), 5) {
		t.Error("delivery 5/5 not read as final")
	}
	if !IsFinalDelivery(delivered(6), 5) {
		t.Error("delivery past MaxDeliver not read as final")
	}
	if IsFinalDelivery(delivered(1), 0) {
		t.Error("delivery read as final with MaxDeliver 0 (unlimited)")
	}
	if IsFinalDelivery(delivered(1), -1) {
		t.Error("delivery read as final with MaxDeliver -1 (unlimited)")
	}
}
// Package natsmsgtest provides test doubles for the jetstream message types
// NATS consumers handle. It lives apart from the packages under test so
// white-box unit tests (package foo, not foo_test) can import it without
// cycles or extra fixture dependencies.
package natsmsgtest

import (
	"context"
	"errors"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
)

// FakeMsg is a jetstream.Msg for unit-testing a consumer's message disposition
// without a live broker. Script the fields the handler reads (SubjectVal,
// DataVal, HeadersVal, Meta) and assert the terminal call it made (Acked,
// Termed, NakDelays, ...). Because jetstream.Msg is an interface — unlike the
// concrete *nats.Msg whose Ack/Nak/Term hit the wire — the disposition is
// directly observable.
type FakeMsg struct {
	SubjectVal string
	DataVal    []byte
	HeadersVal nats.Header
	Meta       *jetstream.MsgMetadata
	MetaErr    error

	Acked       bool
	Termed      bool
	NakDelays   []time.Duration
	InProgressN int
}

func (m *FakeMsg) Subject() string      { return m.SubjectVal }
func (m *FakeMsg) Data() []byte         { return m.DataVal }
func (m *FakeMsg) Headers() nats.Header { return m.HeadersVal }
func (m *FakeMsg) Reply() string        { return "" }

// Metadata returns the scripted metadata, the scripted error, or — when neither
// is set — a non-JetStream error, matching how *nats.Msg.Metadata behaves for a
// message that carries none. Consumers guard this with `if err == nil`.
func (m *FakeMsg) Metadata() (*jetstream.MsgMetadata, error) {
	if m.MetaErr != nil {
		return nil, m.MetaErr
	}
	if m.Meta != nil {
		return m.Meta, nil
	}
	return nil, errors.New("fakemsg: no metadata set")
}

func (m *FakeMsg) Ack() error                      { m.Acked = true; return nil }
func (m *FakeMsg) DoubleAck(context.Context) error { m.Acked = true; return nil }
func (m *FakeMsg) Nak() error                      { return nil }
func (m *FakeMsg) NakWithDelay(d time.Duration) error {
	m.NakDelays = append(m.NakDelays, d)
	return nil
}
func (m *FakeMsg) InProgress() error           { m.InProgressN++; return nil }
func (m *FakeMsg) Term() error                 { m.Termed = true; return nil }
func (m *FakeMsg) TermWithReason(string) error { m.Termed = true; return nil }

var _ jetstream.Msg = (*FakeMsg)(nil)

