import (
	"context"
	"log/slog"
	"runtime/debug"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
)

// DefaultJoinTimeout bounds how long [ShutdownGroup.Shutdown] waits for
// background loops to return before draining the connections anyway.
const DefaultJoinTimeout = 10 * time.Second

// ShutdownGroup coordinates graceful shutdown of a set of background
// pull-consumer loops and the NATS connections they use. It encodes the
// ordering that prevents rollout noise (COR-923): on Shutdown it cancels the
// loops' context, waits for them to return, and only THEN drains the
// connections — so a Drain never races an in-flight Fetch.
//
// Typical use in a service main:
//
//	g := nuts.NewShutdownGroup(ctx)
//	nc, _ := nuts.Connect(g.Context(), url, nuts.WithName("worker"))
//	g.AddConn("worker", nc)
//	g.Go(func(ctx context.Context) { consumer.Run(ctx) }) // returns on ctx.Done
//	<-ctx.Done() // SIGTERM/SIGINT
//	g.Shutdown()
type ShutdownGroup struct {
	ctx          context.Context
	cancel       context.CancelFunc
	logger       *slog.Logger
	joinTimeout  time.Duration
	drainTimeout time.Duration

	wg     sync.WaitGroup
	mu     sync.Mutex
	conns  []groupConn
	closed bool // set under mu once shutdown starts; gates Go registration
	once   sync.Once
}

type groupConn struct {
	name string
	nc   *nats.Conn
}

// GroupOption configures a [ShutdownGroup].
type GroupOption func(*ShutdownGroup)

// WithGroupLogger sets the logger for shutdown diagnostics. Defaults to
// [slog.Default].
func WithGroupLogger(l *slog.Logger) GroupOption { return func(g *ShutdownGroup) { g.logger = l } }

// WithJoinTimeout overrides [DefaultJoinTimeout] — the bound on waiting for
// background loops to return.
func WithJoinTimeout(d time.Duration) GroupOption {
	return func(g *ShutdownGroup) { g.joinTimeout = d }
}

// WithGroupDrainTimeout overrides the fallback subscription-drain budget
// ([DefaultDrainTimeout]) used when draining a registered connection that does
// not carry its own nats.DrainTimeout. A connection created with
// [WithDrainTimeout] is drained on its own budget regardless; the total
// time-to-CLOSED backstop adds publish-flush headroom on top (see [Drain]).
func WithGroupDrainTimeout(d time.Duration) GroupOption {
	return func(g *ShutdownGroup) { g.drainTimeout = d }
}

// NewShutdownGroup returns a group whose context derives from parent and is
// cancelled by [ShutdownGroup.Shutdown].
func NewShutdownGroup(parent context.Context, opts ...GroupOption) *ShutdownGroup {
	//nolint:gosec // cancel is retained in g.cancel and invoked by Shutdown (via shutdown), not leaked
	ctx, cancel := context.WithCancel(parent)
	g := &ShutdownGroup{
		ctx:          ctx,
		cancel:       cancel,
		logger:       slog.Default(),
		joinTimeout:  DefaultJoinTimeout,
		drainTimeout: DefaultDrainTimeout,
	}
	for _, o := range opts {
		o(g)
	}
	if g.logger == nil {
		g.logger = slog.Default()
	}
	return g
}

// Context returns the group's context, cancelled when Shutdown is called. Pass
// it to every background loop and to [Connect] so the loops exit before their
// connections are drained.
func (g *ShutdownGroup) Context() context.Context { return g.ctx }

// Go runs fn as a tracked background loop. fn MUST return when its context is
// cancelled; Shutdown blocks (bounded by the join timeout) until it does.
//
// A panic in fn is recovered and logged with a stack (at ERROR) rather than
// crashing the whole process, so one bad message in one loop does not take down
// every other loop on the pod. A return while the group context is still live
// is treated as a dead subsystem and logged at ERROR too — a tracked loop is
// expected to run until Shutdown cancels it.
//
// Registering a loop after Shutdown has begun is a no-op: the loop would not be
// joined before the connections drain, so it is refused and logged rather than
// started. Go is safe to call concurrently with Shutdown.
func (g *ShutdownGroup) Go(fn func(ctx context.Context)) {
	// Add under the same lock that Shutdown takes before it calls wg.Wait, so a
	// concurrent Go/Shutdown can never race Add against Wait (which panics), and
	// a loop registered after shutdown starts is refused rather than left
	// unjoined.
	g.mu.Lock()
	if g.closed {
		g.mu.Unlock()
		g.logger.WarnContext(g.ctx, "nuts: ShutdownGroup.Go called after shutdown; loop not started")
		return
	}
	g.wg.Add(1)
	g.mu.Unlock()

	go func() {
		defer g.wg.Done()
		defer func() {
			if r := recover(); r != nil {
				g.logger.ErrorContext(g.ctx, "nuts: background loop panicked",
					slog.Any("panic", r), slog.String("stack", string(debug.Stack())))
				return
			}
			// A clean return before the context is cancelled means the loop
			// stopped supervising its subsystem while it was still supposed to
			// be running — surface it instead of letting the pod look healthy.
			if g.ctx.Err() == nil {
				g.logger.ErrorContext(g.ctx, "nuts: background loop returned before shutdown")
			}
		}()
		fn(g.ctx)
	}()
}

// AddConn registers a connection to be drained after the loops have joined.
// Draining last — never before the fetch loops stop — is the ordering that
// keeps a Drain/Close from racing an in-flight Fetch (COR-923).
//
// Like [ShutdownGroup.Go], registering after Shutdown has begun is a no-op:
// the drain set is snapshotted when shutdown starts, so a connection added
// afterward (including during the join window) would never be drained. It is
// refused and logged rather than silently dropped — the caller then owns
// tearing it down. Uses the same lock as shutdown's snapshot, so a connection
// is either in the snapshot or explicitly refused, never lost to a race.
func (g *ShutdownGroup) AddConn(name string, nc *nats.Conn) {
	g.mu.Lock()
	if g.closed {
		g.mu.Unlock()
		g.logger.WarnContext(g.ctx, "nuts: ShutdownGroup.AddConn called after shutdown; connection not registered for drain",
			slog.String("conn", name))
		return
	}
	g.conns = append(g.conns, groupConn{name: name, nc: nc})
	g.mu.Unlock()
}

// Shutdown cancels the group context, waits (bounded by the join timeout) for
// every Go loop to return, then drains every registered connection. It is safe
// to call more than once; only the first call has an effect.
func (g *ShutdownGroup) Shutdown() {
	g.once.Do(g.shutdown)
}

func (g *ShutdownGroup) shutdown() {
	// Mark closed and snapshot the connections under the lock that Go also
	// takes. After this point no new loop can register (see Go), so the wg.Wait
	// below cannot race a concurrent Add.
	g.mu.Lock()
	g.closed = true
	conns := g.conns
	g.mu.Unlock()

	g.cancel()

	done := make(chan struct{})
	go func() {
		g.wg.Wait()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(g.joinTimeout):
		g.logger.WarnContext(g.ctx, "nuts: background loops did not stop within join timeout; draining anyway",
			slog.Duration("join_timeout", g.joinTimeout))
	}

	// Drain the connections concurrently: they are independent, so the group's
	// worst-case shutdown is one drain backstop, not the sum across connections.
	var dwg sync.WaitGroup
	for _, c := range conns {
		dwg.Add(1)
		go func() {
			defer dwg.Done()
			Drain(g.ctx, c.nc, c.name, g.logger, g.drainBackstop(c.nc))
		}()
	}
	dwg.Wait()
}

// drainBackstop returns the total time-to-CLOSED budget for draining nc. It
// honors the connection's own configured nats.DrainTimeout (set via
// [WithDrainTimeout]) when present, falling back to the group's drain timeout,
// then adds headroom for the publish flush nats.go runs after the
// subscription-drain phase so the backstop does not fire mid-drain (see
// [Drain]).
func (g *ShutdownGroup) drainBackstop(nc *nats.Conn) time.Duration {
	subDrain := g.drainTimeout
	if nc != nil && nc.Opts.DrainTimeout > 0 {
		subDrain = nc.Opts.DrainTimeout
	}
	return subDrain + natsPublishDrainTimeout + time.Second
}
package nuts

import (
	"context"
	"errors"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
)

// IsShutdownFetchErr reports whether a pull-consumer Fetch error is the benign
// result of the connection being drained/closed during shutdown rather than a
// real fault. It is only "clean" when ctx is already done — a mid-run
// connection loss (ctx still live) is a genuine error worth logging.
//
// Use it to gate the error log in a fetch loop:
//
//	msgs, err := sub.Fetch(1, nats.MaxWait(5*time.Second))
//	if err != nil {
//		if errors.Is(err, nats.ErrTimeout) || nuts.IsShutdownFetchErr(ctx, err) {
//			// benign: idle poll, or a drain/close during shutdown
//		}
//		...
//	}
func IsShutdownFetchErr(ctx context.Context, err error) bool {
	return ctx.Err() != nil &&
		(errors.Is(err, nats.ErrConnectionClosed) || errors.Is(err, nats.ErrConnectionDraining))
}

// Drain drains nc and waits (bounded by timeout) for it to flush pending
// acks/publishes and reach CLOSED. nats.go's Conn.Drain is asynchronous — it
// starts the drain on a background goroutine and returns immediately — so a
// bare Drain in a shutdown cleanup would let the process exit before the flush
// completes. This subscribes to the connection's CLOSED status event, starts
// the drain, and blocks until the connection closes or timeout elapses. name
// labels the connection in the logs so a wedged drain can be attributed, and
// diagnostics are written to logger (defaulting to [slog.Default] when nil).
//
// timeout is the TOTAL time-to-CLOSED backstop, not the subscription-drain
// budget. The connect-time nats.DrainTimeout option caps only the
// subscription-drain phase; nats.go then runs an unconditional 5s publish flush
// before closing, so the true time-to-CLOSED is up to that flush longer than
// nats.DrainTimeout. timeout must exceed the connection's nats.DrainTimeout by
// at least the publish-flush budget or it will fire mid-drain and drop pending
// acks — [ShutdownGroup] sizes it automatically. timeout bounds how long we
// block; it is not a guarantee the drain finished. Once the consumer loops have
// joined (see [ShutdownGroup]) there is nothing left to drain, so on a reachable
// server this returns in milliseconds; the backstop only bites when the server
// is unreachable.
//
// Unlike a raw nc.Drain, this does not touch the connection's ClosedHandler, so
// a handler installed by [Connect] or by the caller (via [WithNATSOptions]) is
// preserved, and concurrent Drain calls on the same connection do not clobber
// one another.
//
// Drain is a no-op on a nil or already-closed connection.
func Drain(ctx context.Context, nc *nats.Conn, name string, logger *slog.Logger, timeout time.Duration) {
	if logger == nil {
		logger = slog.Default()
	}
	if nc == nil || nc.IsClosed() {
		return
	}

	// Register for the CLOSED transition before starting the drain so it cannot
	// be missed, and via a status listener rather than SetClosedHandler so we
	// never displace a handler the connection already has.
	closed := nc.StatusChanged(nats.CLOSED)
	defer nc.RemoveStatusListener(closed)

	if err := nc.Drain(); err != nil {
		logger.WarnContext(ctx, "nuts: NATS drain failed; closing",
			slog.String("conn", name), slog.Any("error", err))
		nc.Close()
		return
	}

	select {
	case <-closed:
		logger.InfoContext(ctx, "nuts: NATS drained", slog.String("conn", name))
	case <-time.After(timeout):
		logger.WarnContext(ctx, "nuts: NATS drain timed out before close", slog.String("conn", name))
	}
}
package nuts

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"time"

	"github.com/nats-io/nats.go"
)

// Default connection tunables. DefaultDrainTimeout matches entire-core's tuned
// value (COR-923); nats.go's own default is 30s. It caps only the
// subscription-drain phase — see [Drain] for why it is not the whole budget.
const (
	DefaultDrainTimeout  = 5 * time.Second
	DefaultReconnectWait = 2 * time.Second
)

// natsPublishDrainTimeout is the fixed publish-flush budget nats.go spends
// after the subscription-drain phase before a drained connection reaches CLOSED
// (the hardcoded FlushTimeout in (*nats.Conn).drainConnection). A total
// time-to-CLOSED backstop must exceed a connection's nats.DrainTimeout by at
// least this much, plus a little slack, to avoid firing mid-flush.
const natsPublishDrainTimeout = 5 * time.Second

// Environment variables that carry the org-wide mTLS client identity. The same
// triple is consumed by every Entire service that dials NATS.
const (
	envTLSCert = "ENTIRE_INTERNAL_TLS_CERT_FILE"
	envTLSKey  = "ENTIRE_INTERNAL_TLS_KEY_FILE"
	envTLSCA   = "ENTIRE_INTERNAL_TLS_CA_FILE"
)

// config holds the resolved connection settings. Callers mutate it through
// [Option] values.
type config struct {
	name                 string
	logger               *slog.Logger
	tlsConfig            *tls.Config
	tlsFromEnv           bool
	drainTimeout         time.Duration
	reconnectWait        time.Duration
	maxReconnects        int
	retryOnFailedConnect bool
	extra                []nats.Option
}

// Option configures a [Connect] call.
type Option func(*config)

// WithName sets the NATS connection name (nats.Name), which labels the client
// in server monitoring and in the logs.
func WithName(name string) Option { return func(c *config) { c.name = name } }

// WithLogger sets the logger used for connection lifecycle events. Defaults to
// [slog.Default]. Context-aware log methods are used, so a handler that reads
// trace context from the context still works.
func WithLogger(l *slog.Logger) Option { return func(c *config) { c.logger = l } }

// WithTLSConfig supplies an explicit *tls.Config and disables the default
// env-var mTLS lookup. Pass this (or [WithoutTLS]) when the standard
// ENTIRE_INTERNAL_TLS_* identity does not apply.
func WithTLSConfig(t *tls.Config) Option {
	return func(c *config) {
		c.tlsConfig = t
		c.tlsFromEnv = false
	}
}

// WithoutTLS disables TLS entirely (plaintext). Intended for local development
// and tests against an embedded server; production dials always use mTLS.
func WithoutTLS() Option {
	return func(c *config) {
		c.tlsConfig = nil
		c.tlsFromEnv = false
	}
}

// WithDrainTimeout overrides [DefaultDrainTimeout].
func WithDrainTimeout(d time.Duration) Option { return func(c *config) { c.drainTimeout = d } }

// WithReconnectWait overrides [DefaultReconnectWait].
func WithReconnectWait(d time.Duration) Option { return func(c *config) { c.reconnectWait = d } }

// WithRetryOnFailedConnect keeps [Connect] from returning an error when the
// initial dial fails: nats.go instead returns a connection in RECONNECTING
// state and retries in the background (buffering publishes). It is off by
// default so a misconfigured connection (bad URL, wrong TLS material) fails
// fast at startup — crash-looping the pod so a bad rollout is visible — rather
// than silently accepting work it cannot deliver. Enable it only for
// optional/secondary connections a service is designed to run without.
func WithRetryOnFailedConnect() Option {
	return func(c *config) { c.retryOnFailedConnect = true }
}

// WithNATSOptions appends raw nats.Option values, applied after nuts's
// defaults so a caller can override any of them. An escape hatch for options
// nuts does not model.
func WithNATSOptions(opts ...nats.Option) Option {
	return func(c *config) { c.extra = append(c.extra, opts...) }
}

// Connect opens a NATS connection with the org-standard resiliency posture:
// rotation-aware mTLS (from the ENTIRE_INTERNAL_TLS_* env vars unless
// overridden), reconnect-forever (long-lived services must outlive arbitrary
// NATS outages rather than permanently CLOSE after the client default of 60
// attempts), a bounded drain timeout, and lifecycle handlers that log at the
// right level — notably routing the nil-error DisconnectErr that nats.go fires
// on an explicit Close to INFO, so a clean shutdown does not look like a fault.
//
// The initial dial is fail-fast: if the first connect does not succeed Connect
// returns an error, so a misconfigured service crash-loops visibly rather than
// booting into a broken state. Reconnect-forever applies only once a connection
// has been established. Pass [WithRetryOnFailedConnect] to opt into background
// retry of the initial dial instead.
//
// The returned connection should be torn down with [Drain] (or via a
// [ShutdownGroup]) on graceful shutdown, not nc.Close, so in-flight work
// finishes and pull-consumer fetch loops exit cleanly.
func Connect(ctx context.Context, url string, opts ...Option) (*nats.Conn, error) {
	if url == "" {
		return nil, errors.New("nuts: nats url is empty")
	}
	cfg := config{
		logger:        slog.Default(),
		tlsFromEnv:    true,
		drainTimeout:  DefaultDrainTimeout,
		reconnectWait: DefaultReconnectWait,
		maxReconnects: -1,
	}
	for _, o := range opts {
		o(&cfg)
	}
	if cfg.logger == nil {
		cfg.logger = slog.Default()
	}

	var tlsConf *tls.Config
	switch {
	case cfg.tlsConfig != nil:
		tlsConf = cfg.tlsConfig
	case cfg.tlsFromEnv:
		var err error
		if tlsConf, err = tlsConfigFromEnv(); err != nil {
			return nil, err
		}
	}

	// The lifecycle handlers below outlive the Connect call — they fire on
	// disconnects and reconnects for the whole life of the connection, long
	// after a startup- or request-scoped ctx is cancelled. Log through a
	// cancellation-detached copy so a context-aware slog handler still sees the
	// trace values but never drops a mid-life event because ctx is already done.
	logCtx := context.WithoutCancel(ctx)
	connAttr := slog.String("conn", cfg.name)

	natsOpts := []nats.Option{
		nats.DrainTimeout(cfg.drainTimeout),
		nats.RetryOnFailedConnect(cfg.retryOnFailedConnect),
		nats.MaxReconnects(cfg.maxReconnects),
		nats.ReconnectWait(cfg.reconnectWait),
		nats.DisconnectErrHandler(func(_ *nats.Conn, err error) {
			// nats.go fires this with err==nil when the caller calls Close()
			// explicitly (see nats.Options.DisconnectedErrCB). Logging that at
			// ERROR makes clean shutdowns look like failures, so route the
			// explicit-close case to INFO.
			if err == nil {
				cfg.logger.InfoContext(logCtx, "nuts: NATS disconnected", connAttr)
				return
			}
			cfg.logger.ErrorContext(logCtx, "nuts: NATS disconnected", connAttr, slog.Any("error", err))
		}),
		nats.ClosedHandler(func(_ *nats.Conn) {
			cfg.logger.InfoContext(logCtx, "nuts: NATS connection closed", connAttr)
		}),
		nats.ReconnectHandler(func(_ *nats.Conn) {
			cfg.logger.InfoContext(logCtx, "nuts: NATS reconnected", connAttr)
		}),
		nats.ReconnectErrHandler(func(_ *nats.Conn, err error) {
			cfg.logger.ErrorContext(logCtx, "nuts: NATS reconnect failed", connAttr, slog.Any("error", err))
		}),
	}
	if tlsConf != nil {
		natsOpts = append(natsOpts, nats.Secure(tlsConf))
	}
	if cfg.name != "" {
		natsOpts = append(natsOpts, nats.Name(cfg.name))
	}
	natsOpts = append(natsOpts, cfg.extra...)

	nc, err := nats.Connect(url, natsOpts...)
	if err != nil {
		return nil, fmt.Errorf("nuts: connect to NATS: %w", err)
	}
	// With RetryOnFailedConnect enabled, nats.Connect returns a nil error even
	// when the initial dial failed — the connection is in RECONNECTING and the
	// client is retrying in the background. Report that honestly instead of
	// claiming "connected".
	if status := nc.Status(); status != nats.CONNECTED {
		cfg.logger.WarnContext(ctx, "nuts: NATS not yet connected; retrying in background",
			connAttr, slog.String("url", url), slog.String("status", status.String()))
		return nc, nil
	}
	cfg.logger.InfoContext(ctx, "nuts: NATS connected", connAttr, slog.String("url", url))
	return nc, nil
}

// tlsConfigFromEnv builds the mTLS config from the ENTIRE_INTERNAL_TLS_* env
// vars, requiring all three to be set.
func tlsConfigFromEnv() (*tls.Config, error) {
	cert, key, ca := os.Getenv(envTLSCert), os.Getenv(envTLSKey), os.Getenv(envTLSCA)
	if cert == "" || key == "" || ca == "" {
		return nil, fmt.Errorf("nuts: %s, %s, %s all required for NATS mTLS", envTLSCert, envTLSKey, envTLSCA)
	}
	return TLSConfigFromFiles(cert, key, ca)
}

