// Package jsconsumer factors the durable JetStream pull-consumer scaffold shared by
// the service's decode-and-dispatch lifecycle consumers (repolifecycle,
// settingsconsumer, mirrorlifecycle). Each of those hand-rolled the same lifecycle:
// jetstream.New → CreateOrUpdateConsumer (durable, explicit ack, 30s ack-wait,
// bounded MaxDeliver, filter subject) → Consume → stop on context cancel; and the
// same per-message prologue: open a consumer span (re-parented across the NATS hop),
// decode the payload, and Term on a decode error.
//
// This package owns exactly that scaffold and nothing else. Each consumer keeps its
// OWN event type, business dispatch (op switch, seed/apply/push), metrics, and log
// lines — Start takes the consumer's message callback, and Process invokes the
// consumer's handle with the decoded event and the live span.
package jsconsumer

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/entire-api/internal/otelnats"
	"github.com/entirehq/entire-api/internal/otelsetup"
)

const (
	// ackWait is how long JetStream waits for an ack before redelivery — shared by
	// every consumer here (30s: comfortably longer than a Core round-trip + a DB
	// upsert, short enough that a stuck message redelivers promptly).
	ackWait = 30 * time.Second
	// defaultMaxDeliver caps redelivery before JetStream terms a message when the
	// caller leaves Config.MaxDeliver zero — the posture the migrated consumers share.
	defaultMaxDeliver = 8
)

// Config describes the durable consumer to create and how to trace/log it. The
// filter is given as either FilterSubject (single) or FilterSubjects (multi),
// mirroring jetstream.ConsumerConfig, so a migrated consumer preserves its existing
// on-server filter form exactly.
type Config struct {
	Stream         string   // JetStream stream to bind (must already exist)
	Durable        string   // durable consumer name, stable across restarts
	FilterSubject  string   // set this OR FilterSubjects
	FilterSubjects []string // set this OR FilterSubject
	MaxDeliver     int      // 0 → defaultMaxDeliver
	SpanName       string   // per-message consumer span name (e.g. "repolifecycle.consume")
	Name           string   // short package name, used in the decode-error log prefix
}

// Runner is a live consume loop. Stop halts it and is idempotent.
type Runner struct{ cc jetstream.ConsumeContext }

// Stop halts the consume loop. Safe on a nil Runner and safe to call twice.
func (r *Runner) Stop() {
	if r != nil && r.cc != nil {
		r.cc.Stop()
		r.cc = nil
	}
}

// Start creates/updates the durable consumer on nc and begins delivering messages to
// onMsg, returning a Runner that Stops when ctx is cancelled. The stream must already
// exist (provisioned declaratively in fleet); callers gate Start behind their per-cell
// opt-in so a cell without the stream doesn't error at CreateOrUpdateConsumer.
func Start(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) (*Runner, error) {
	if nc == nil {
		return nil, fmt.Errorf("jsconsumer(%s): nil nats conn", cfg.Name)
	}
	js, err := jetstream.New(nc)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): jetstream.New: %w", cfg.Name, err)
	}
	maxDeliver := cfg.MaxDeliver
	if maxDeliver == 0 {
		maxDeliver = defaultMaxDeliver
	}
	cons, err := js.CreateOrUpdateConsumer(ctx, cfg.Stream, jetstream.ConsumerConfig{
		Durable:        cfg.Durable,
		AckPolicy:      jetstream.AckExplicitPolicy,
		AckWait:        ackWait,
		MaxDeliver:     maxDeliver,
		FilterSubject:  cfg.FilterSubject,
		FilterSubjects: cfg.FilterSubjects,
	})
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): create consumer %s/%s: %w", cfg.Name, cfg.Stream, cfg.Durable, err)
	}
	cc, err := cons.Consume(onMsg)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): consume %s: %w", cfg.Name, cfg.Stream, err)
	}
	r := &Runner{cc: cc}
	go func() {
		<-ctx.Done()
		r.Stop()
	}()
	return r, nil
}

// Process runs the per-message prologue shared by every consumer: open the consumer
// span (re-parented to the producer across the NATS hop), decode the payload, and on
// a decode error record it, log "<Name>: decode <Stream>; term", invoke onUndecodable
// (so the caller bumps its own drop metric with its own attributes), and Term the
// message — a poison payload won't decode on redelivery. On success it invokes handle
// with the span-enriched context, the live span (for RecordError/SetStatus on the
// business error paths), the message, and the decoded event.
//
// Callers wire Process as the func they pass to Start AND the entry point their tests
// drive, so the decode-or-term path is exercised the same way in production and tests.
func Process[E any](
	ctx context.Context,
	msg jetstream.Msg,
	cfg Config,
	decode func([]byte) (E, error),
	handle func(ctx context.Context, span trace.Span, msg jetstream.Msg, ev E),
	onUndecodable func(ctx context.Context),
) {
	ctx, span := otelnats.StartConsumerSpan(ctx, otelsetup.Tracer(), msg, cfg.SpanName)
	defer span.End()

	ev, err := decode(msg.Data())
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		slog.WarnContext(ctx, cfg.Name+": decode "+cfg.Stream+"; term",
			slog.Any("error", err), slog.String("subject", msg.Subject()))
		if onUndecodable != nil {
			onUndecodable(ctx)
		}
		_ = msg.Term()
		return
	}
	handle(ctx, span, msg, ev)
}

package repolifecycle

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/entire-api/internal/coreapi"
	"github.com/entirehq/entire-api/internal/jsconsumer"
	"github.com/entirehq/entire-api/internal/store"
)

// consumerCfg is the durable pull-consumer descriptor for the repo arm, shared by
// Start (create the consumer) and handle (the per-message span+decode prologue).
var consumerCfg = jsconsumer.Config{
	Stream:         StreamName,
	Durable:        consumerDurable,
	FilterSubjects: []string{subjectRepo},
	MaxDeliver:     consumerMaxDeliver,
	SpanName:       "repolifecycle.consume",
	Name:           "repolifecycle",
}

// consumerDurable is the durable consumer name on each cell's
// resource_lifecycle_v1 stream. One per deployment, stable across restarts;
// distinct from the re-attribution consumer that binds the identity arms.
const consumerDurable = "repo-lifecycle-consumer"

// consumerMaxDeliver caps redelivery before JetStream terms a message — same
// posture as the reattribute / github_meta / ingest consumers.
const consumerMaxDeliver = 8

// CoreClient is the subset of coreapi.Client this package needs: re-query a repo
// by id over entire-core's internal mTLS listener (COR-593). The lifecycle event
// is a thin projection, so the repo's owning project + path come from this read.
type CoreClient interface {
	GetRepo(ctx context.Context, repoID string) (*coreapi.Repo, error)
}

// Store is the repos-table surface: the provisioning upsert + delete.
type Store interface {
	UpsertRepo(ctx context.Context, r store.Repo) error
	DeleteRepo(ctx context.Context, repoID string) error
}

// SeedRepo re-queries core for a repo's metadata and upserts its repos row. Shared
// by the lifecycle consumer (repo.created arm) and the seed-repos backfill so both
// seed identically. Returns (false, nil) when core reports the repo gone (404) —
// the caller treats that as a benign skip, never an error (a created event raced a
// delete, or a backfill list went stale). The seeded row carries no
// default_branch; the ingester resolves it lazily on first push, and UpsertRepo
// preserves that resolved branch against this empty seed.
//
// The row is stamped with repo_group_id from the Core read: for a mirror that
// is the upstream's placement-independent repo_group ULID (empty for a native
// repo, which has no upstream group). The row is thus born with its origin
// before any push or forward. The repo_refs_v1 ref event carries the same fact
// on the live-push path (ensureRepo), a belt-and-suspenders refresh; and
// UpsertRepo's COALESCE preserves a resolved group against a later empty seed,
// so this only ever fills a NULL.
func SeedRepo(ctx context.Context, core CoreClient, st Store, jurisdiction, repoID string) (bool, error) {
	r, err := core.GetRepo(ctx, repoID)
	if errors.Is(err, coreapi.ErrNotFound) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("repolifecycle: get repo %s: %w", repoID, err)
	}
	if err := SeedRepoFrom(ctx, st, jurisdiction, r); err != nil {
		return false, err
	}
	return true, nil
}

// repoUpserter is the write half SeedRepoFrom needs — the UpsertRepo subset of
// Store. Narrower than Store so a caller that reuses the seed mapping but has no
// delete surface (the mirror-lifecycle consumer) can pass its own store without
// implementing DeleteRepo.
type repoUpserter interface {
	UpsertRepo(ctx context.Context, r store.Repo) error
}

// IsHomeCell reports whether cell homes a resource_lifecycle event stamped with
// eventJurisdiction — the seed guard both lifecycle consumers share (repo.created
// here, mirror.created in mirrorlifecycle). resourceevents stamps every event with
// the resource's home region, so a present, matching jurisdiction means this cell
// homes the resource. It FAILS OPEN on an empty jurisdiction (an event from a core
// predating the stamp): a missing field never drops a home resource. Once
// meta-fanout fans repo.*/mirror.* cross-region this excludes foreign resources;
// until then it is a no-op, since every event a cell receives is its own.
func IsHomeCell(eventJurisdiction, cell string) bool {
	return eventJurisdiction == "" || eventJurisdiction == cell
}

// SeedRepoFrom upserts a repos row from an already-fetched Core repo, stamped with
// jurisdiction. It is the body SeedRepo runs after its GetRepo, exported so a caller
// that already holds the Core read — the mirror-lifecycle consumer, which reads the
// repo for its jurisdiction guard + repo_group id — seeds identically without a
// second Core round-trip. The mapping (id / owning project / full name / repo_group)
// lives here once so the two seed paths can't drift; UpsertRepo's COALESCE preserves
// a resolved default_branch / repo_group against this branch-less seed.
func SeedRepoFrom(ctx context.Context, st repoUpserter, jurisdiction string, r *coreapi.Repo) error {
	return st.UpsertRepo(ctx, store.Repo{
		ID:              r.ID,
		OwningProjectID: r.OwningProjectID,
		Jurisdiction:    jurisdiction,
		FullName:        r.RepoFullName(),
		RepoGroupID:     r.RepoGroupID,
		IsMirror:        r.Mirror != nil,
	})
}

// Consumer durably pulls the repo arm of this cell's local resource_lifecycle_v1
// stream and keeps the repos table in step with provisioning.
type Consumer struct {
	nc           *nats.Conn
	core         CoreClient
	store        Store
	jurisdiction string
	m            metrics

	run *jsconsumer.Runner
}

// NewConsumer constructs a Consumer. core re-queries repo metadata (the event is a
// thin projection); jurisdiction stamps the seeded rows (this cell's region).
func NewConsumer(nc *nats.Conn, core CoreClient, st Store, jurisdiction string) *Consumer {
	return &Consumer{nc: nc, core: core, store: st, jurisdiction: jurisdiction, m: newMetrics()}
}

// Start creates the durable consumer and begins consuming. Returns immediately.
// The local resource_lifecycle_v1 stream must already exist (provisioned in
// fleet); the caller gates Start behind CONSUME_REPO_LIFECYCLE so a cell without
// the stream doesn't error in CreateOrUpdateConsumer.
func (c *Consumer) Start(ctx context.Context) error {
	if c == nil || c.nc == nil {
		return errors.New("repolifecycle: Consumer not initialised")
	}
	if c.core == nil || c.store == nil {
		return errors.New("repolifecycle: Consumer.core and Consumer.store required")
	}
	run, err := jsconsumer.Start(ctx, c.nc, consumerCfg, func(msg jetstream.Msg) { c.handle(ctx, msg) })
	if err != nil {
		return err
	}
	c.run = run
	slog.InfoContext(ctx, "resource_lifecycle repo seeding consumer started",
		slog.String("jurisdiction", c.jurisdiction))
	return nil
}

// Stop halts the consume loop. Idempotent.
func (c *Consumer) Stop() error {
	c.run.Stop()
	return nil
}

// decodeEvent is the payload decoder for the shared prologue.
func decodeEvent(b []byte) (Event, error) {
	var ev Event
	err := json.Unmarshal(b, &ev)
	return ev, err
}

// handle is the per-message entry point (production callback + test seam): the shared
// span+decode-or-term prologue, then onEvent for a decoded event.
func (c *Consumer) handle(ctx context.Context, msg jetstream.Msg) {
	jsconsumer.Process(ctx, msg, consumerCfg, decodeEvent, c.onEvent, func(ctx context.Context) {
		c.m.dropped.Add(ctx, 1, attr("reason", "undecodable"))
	})
}

func (c *Consumer) onEvent(ctx context.Context, span trace.Span, msg jetstream.Msg, ev Event) {
	if ev.ResourceType != typeRepo {
		// The filter subject is the repo arm, so this is defensive only — ack rather
		// than churn redelivery on a misrouted event.
		c.m.skipped.Add(ctx, 1, attr("reason", "not_repo"))
		_ = msg.Ack()
		return
	}
	if ev.ResourceID == "" {
		// No repo to act on — redelivery won't help. Term.
		slog.WarnContext(ctx, "repolifecycle: event missing repo id; term", slog.String("subject", msg.Subject()))
		c.m.dropped.Add(ctx, 1, attr("reason", "missing_repo"))
		_ = msg.Term()
		return
	}

	switch ev.Op {
	case opCreated:
		// Skip a repo homed in another cell: seeding it would stamp this cell's
		// jurisdiction on a foreign repo once meta-fanout fans repo.* cross-region.
		// IsHomeCell fails open on an empty stamp; see its doc.
		if !IsHomeCell(ev.Jurisdiction, c.jurisdiction) {
			c.m.skipped.Add(ctx, 1, attr("reason", "foreign"))
			_ = msg.Ack()
			return
		}
		found, err := SeedRepo(ctx, c.core, c.store, c.jurisdiction, ev.ResourceID)
		if err != nil {
			// Transient (core read / store blip) — nak for redelivery. The upsert is
			// idempotent, so a replay is safe.
			span.RecordError(err)
			span.SetStatus(codes.Error, "seed")
			slog.WarnContext(ctx, "repolifecycle: seed repo failed; nak", slog.Any("error", err), slog.String("repo_id", ev.ResourceID))
			_ = msg.Nak()
			return
		}
		if !found {
			// Core already reports the repo gone — a created event that raced its own
			// delete. Nothing to seed; ack.
			c.m.skipped.Add(ctx, 1, attr("reason", "gone"))
			_ = msg.Ack()
			return
		}
		c.m.seeded.Add(ctx, 1)
		_ = msg.Ack()
		// Repo lifecycle events are low frequency, so a per-event success line is fine.
		slog.InfoContext(ctx, "repolifecycle: repo seeded", slog.String("repo_id", ev.ResourceID))
	case opDeleted:
		if err := c.store.DeleteRepo(ctx, ev.ResourceID); err != nil {
			span.RecordError(err)
			span.SetStatus(codes.Error, "delete")
			slog.WarnContext(ctx, "repolifecycle: delete repo failed; nak", slog.Any("error", err), slog.String("repo_id", ev.ResourceID))
			_ = msg.Nak()
			return
		}
		c.m.deleted.Add(ctx, 1)
		_ = msg.Ack()
		slog.InfoContext(ctx, "repolifecycle: repo deleted", slog.String("repo_id", ev.ResourceID))
	default:
		// An op this consumer doesn't act on (additive producer contract) — ack.
		c.m.skipped.Add(ctx, 1, attr("reason", "unhandled_op"))
		_ = msg.Ack()
	}
}

