 27	// consumer configs default it) returns a no-op stop.
 28	//
 29	// stop is idempotent and blocks until the ticker goroutine has exited, so
 30	// no InProgress can race a terminal disposition (Ack/Nak/Term) issued
 31	// after it returns.
 32	func KeepInProgress(inProgress func() error, ackWait time.Duration) (stop func()) {
 33		interval := ackWait / 3
 34		if interval <= 0 {
 35			return func() {}
 36		}
 37		done := make(chan struct{})
 38		finished := make(chan struct{})
 39		go func() {
 40			defer close(finished)
 41			ticker := time.NewTicker(interval)
 42			defer ticker.Stop()
 43			for ticks := 0; ; {
 44				select {
 45				case <-done:
 46					return
 47				case <-ticker.C:
 48					ticks++
 49					if ticks > keepInProgressMaxTicks {
 50						return
 51					}
 52					if err := inProgress(); err != nil {
 53						// A delivery that can't be extended (no JetStream
 54						// reply subject, or already terminally disposed)
 55						// won't start succeeding on a later tick; stop
 56						// instead of spinning. The real failure surfaces
 57						// on the terminal Ack/Nak/Term.
 58						return
 59					}
 60				}
 61			}
 62		}()
 63		var once sync.Once
 64		return func() {
 65			once.Do(func() { close(done) })
 66			<-finished
 67		}
 68	}
