119	// Runner is a live consume loop. Stop halts it and is idempotent.
120	type Runner struct{ cc jetstream.ConsumeContext }
121	
122	// Stop halts the consume loop. Safe on a nil Runner and safe to call twice.
123	func (r *Runner) Stop() {
124		if r != nil && r.cc != nil {
125			r.cc.Stop()
126			r.cc = nil
127		}
128	}
