130	// Start creates/updates the durable consumer on nc and begins delivering
131	// messages to onMsg, returning a Runner that Stops when ctx is cancelled. The
132	// stream must already exist (provisioned declaratively); callers whose cells
133	// opt in per-stream gate Start behind that opt-in so a cell without the stream
134	// doesn't error at CreateOrUpdateConsumer.
135	//
136	// Consume errors are logged at Warn, except a drain/close during shutdown
137	// ([nuts.IsShutdownFetchErr]), which is a clean exit rather than a fault.
138	func Start(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) (*Runner, error) {
139		if nc == nil {
140			return nil, fmt.Errorf("jsconsumer(%s): nil nats conn", cfg.Name)
141		}
142		js, err := jetstream.New(nc)
143		if err != nil {
144			return nil, fmt.Errorf("jsconsumer(%s): jetstream.New: %w", cfg.Name, err)
145		}
146		cons, err := js.CreateOrUpdateConsumer(ctx, cfg.Stream, jetstream.ConsumerConfig{
147			Durable:        cfg.Durable,
148			AckPolicy:      jetstream.AckExplicitPolicy,
149			AckWait:        cfg.EffectiveAckWait(),
150			MaxDeliver:     cfg.EffectiveMaxDeliver(),
151			FilterSubject:  cfg.FilterSubject,
152			FilterSubjects: cfg.FilterSubjects,
153		})
154		if err != nil {
155			return nil, fmt.Errorf("jsconsumer(%s): create consumer %s/%s: %w", cfg.Name, cfg.Stream, cfg.Durable, err)
156		}
157		cc, err := cons.Consume(onMsg, jetstream.ConsumeErrHandler(func(_ jetstream.ConsumeContext, cerr error) {
158			if nuts.IsShutdownFetchErr(ctx, cerr) {
159				return
160			}
161			cfg.logger().WarnContext(ctx, cfg.Name+": consume error", slog.Any("error", cerr))
162		}))
163		if err != nil {
164			return nil, fmt.Errorf("jsconsumer(%s): consume %s: %w", cfg.Name, cfg.Stream, err)
165		}
166		r := &Runner{cc: cc}
167		go func() {
168			<-ctx.Done()
169			r.Stop()
170		}()
171		return r, nil
172	}
