174	// Process runs the per-message prologue shared by every consumer: open the
175	// consumer span (re-parented to the producer across the NATS hop), decode the
176	// payload, and on a decode error record it, log "<Name>: decode <Stream>;
177	// term", invoke onUndecodable (so the caller bumps its own drop metric with
178	// its own attributes), and Term the message — a poison payload won't decode on
179	// redelivery. On success it invokes handle with the span-enriched context, the
180	// live span (for RecordError/SetStatus on the business error paths), the
181	// message, and the decoded event; with Config.KeepInProgress set, an AckWait
182	// heartbeat runs for the duration of handle.
183	//
184	// Callers wire Process as the func they pass to Start AND the entry point
185	// their tests drive, so the decode-or-term path is exercised the same way in
186	// production and tests.
187	func Process[E any](
188		ctx context.Context,
189		msg jetstream.Msg,
190		cfg Config,
191		decode func([]byte) (E, error),
192		handle func(ctx context.Context, span trace.Span, msg jetstream.Msg, ev E),
193		onUndecodable func(ctx context.Context),
194	) {
195		ctx, span := natsmsg.StartConsumerSpan(ctx, cfg.tracer(), msg, cfg.SpanName)
196		defer span.End()
197	
198		ev, err := decode(msg.Data())
199		if err != nil {
200			span.RecordError(err)
201			span.SetStatus(codes.Error, "decode")
202			cfg.logger().WarnContext(ctx, cfg.Name+": decode "+cfg.Stream+"; term",
203				slog.Any("error", err), slog.String("subject", msg.Subject()))
204			if onUndecodable != nil {
205				onUndecodable(ctx)
206			}
207			if termErr := msg.Term(); termErr != nil {
208				cfg.logger().WarnContext(ctx, cfg.Name+": term failed", slog.Any("error", termErr))
209			}
210			return
211		}
212		if cfg.KeepInProgress {
213			stop := natsmsg.KeepInProgress(msg.InProgress, cfg.EffectiveAckWait())
214			defer stop()
215		}
216		handle(ctx, span, msg, ev)
217	}

